        AGENT_READ_RESULT,
    ));

    let rewrite = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(
        rewrite.tool, "bash",
        "a repeated identifier needs one bounded replace-all operation"
    );
    assert_eq!(
        json_arguments(&rewrite.arguments)["command"],
        "perl -pi -e 's/\\bWEB_SEARCH_RRF_K\\b/WEB_SEARCH_FUSION_K/g' -- rust/src/web_search_core.rs",
        "the operation must be derived only from validated identifiers and path, \
         and scoped to whole words so a longer name containing this one survives"
    );
    push_result(&mut messages, "agent_rewrite", &rewrite, "");

    let verify = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(
        verify.tool, "bash",
        "the bounded rewrite result must advance"
    );
    assert_eq!(
        json_arguments(&verify.arguments)["command"],
        "sha256sum -- rust/src/web_search_core.rs",
        "verification must not return the whole large source through Agent"
    );
    let digest = formal_ai::sha256_hex(AFTER.as_bytes());
    push_result(
        &mut messages,
        "agent_verify",
        &verify,
        &format!("{digest}  rust/src/web_search_core.rs\n"),
    );

    let Some(AgenticPlan::Final(answer)) = plan_chat_step(&messages, &tools) else {
        panic!("the compact Agent rewrite must finish");
    };
    assert!(answer.contains("observed"), "{answer}");
}

#[test]
fn composite_module_request_creates_source_and_registers_the_module() {
    const TASK: &str = "Create rust/src/ladder_units.rs with a public function \
        metres_to_kilometres dividing an f64 by 1000.0, and register the module in rust/src/lib.rs \
        so it is part of the crate.";
    const MODULE: &str = concat!(
        "pub fn metres_to_kilometres(value: f64) -> f64 {\n",
        "    value / 1000.0\n",
        "}\n",
    );
    const LIB_BEFORE: &str = "pub mod language;\npub mod seed;\n";
    const LIB_AFTER: &str = "pub mod language;\npub mod seed;\npub mod ladder_units;\n";
    let tools = ["read_file", "write_file", "run_command"];
    let mut messages = vec![ChatMessage::user(TASK)];

    let create = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(create.tool, "write_file");
    let arguments = json_arguments(&create.arguments);
    assert_eq!(arguments["path"], "rust/src/ladder_units.rs");
    assert_eq!(arguments["content"], MODULE);
    push_result(&mut messages, "write_module", &create, "created");

    let verify_module = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(verify_module.tool, "run_command");
    assert_eq!(
        json_arguments(&verify_module.arguments)["command"],
        "cat rust/src/ladder_units.rs"
    );
    push_result(
        &mut messages,
        "verify_module",
        &verify_module,
        &serde_json::json!({"stdout": MODULE, "exit_code": 0}).to_string(),
    );

    let read_lib = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(read_lib.tool, "read_file");
    assert_eq!(
        json_arguments(&read_lib.arguments)["path"],
        "rust/src/lib.rs"
    );
    push_result(&mut messages, "read_lib", &read_lib, LIB_BEFORE);

    let write_lib = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(write_lib.tool, "write_file");
    let arguments = json_arguments(&write_lib.arguments);
    assert_eq!(arguments["path"], "rust/src/lib.rs");
    assert_eq!(arguments["content"], LIB_AFTER);
    push_result(&mut messages, "write_lib", &write_lib, "updated");

    let verify_lib = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(verify_lib.tool, "run_command");
    assert_eq!(
        json_arguments(&verify_lib.arguments)["command"],
        "cat rust/src/lib.rs"
    );
    push_result(
        &mut messages,
        "verify_lib",
        &verify_lib,
        &serde_json::json!({"stdout": LIB_AFTER, "exit_code": 0}).to_string(),
    );

    let Some(AgenticPlan::Final(answer)) = plan_chat_step(&messages, &tools) else {
        panic!("a fully observed composite change must finish");
    };
    assert!(answer.contains("observed"), "{answer}");
}

#[test]
fn composite_module_uses_a_compact_agent_registration_edit() {
    const TASK: &str = "Create rust/src/ladder_units.rs with a public function \
        metres_to_kilometres dividing an f64 by 1000.0, and register the module in rust/src/lib.rs \
        so it is part of the crate.";
    const MODULE: &str = concat!(
        "pub fn metres_to_kilometres(value: f64) -> f64 {\n",
        "    value / 1000.0\n",
        "}\n",
    );
    const LIB_AFTER: &str = "pub mod language;\npub mod seed;\npub mod ladder_units;\n";
    const AGENT_LIB_READ: &str = concat!(
        "<file>\n",
        "00001| pub mod language;\n",
        "00002| pub mod seed;\n",
        "00003| \n\n",
        "(End of file - total 3 lines)\n",
        "</file>",
    );
    let tools = ["read", "edit", "write", "bash"];
    let mut messages = vec![ChatMessage::user(TASK)];

    let create = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(create.tool, "write");
    push_result(&mut messages, "agent_create_module", &create, "");

    let verify_module = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(verify_module.tool, "bash");
    push_result(
        &mut messages,
        "agent_verify_module",
        &verify_module,
        &serde_json::json!({"stdout": MODULE, "exit_code": 0}).to_string(),
    );

    let read_lib = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(read_lib.tool, "read");
    messages.push(ChatMessage::assistant_tool_calls(vec![ToolCall::function(
        "agent_read_lib",
        "read",
        serde_json::json!({"filePath": "/tmp/agent-workspace/rust/src/lib.rs"}).to_string(),
    )]));
    messages.push(ChatMessage::tool_result(
        "agent_read_lib",
        "read",
        AGENT_LIB_READ,
    ));

    let edit_lib = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(
        edit_lib.tool, "edit",
        "module registration must not echo all of rust/src/lib.rs through write"
    );
    let arguments = json_arguments(&edit_lib.arguments);
    assert_eq!(arguments["oldString"], "pub mod seed;\n");
    assert_eq!(
        arguments["newString"],
        "pub mod seed;\npub mod ladder_units;\n"
    );
    messages.push(ChatMessage::assistant_tool_calls(vec![ToolCall::function(
        "agent_edit_lib",
        "edit",
        serde_json::json!({
            "filePath": "/tmp/agent-workspace/rust/src/lib.rs",
            "oldString": "pub mod seed;\n",
            "newString": "pub mod seed;\npub mod ladder_units;\n",
        })
        .to_string(),
    )]));
    messages.push(ChatMessage::tool_result("agent_edit_lib", "edit", ""));

    let verify_lib = only_call(plan_chat_step(&messages, &tools));
    assert_eq!(verify_lib.tool, "bash");
    assert_eq!(
        json_arguments(&verify_lib.arguments)["command"],
        "sha256sum -- rust/src/lib.rs"
    );
    let digest = formal_ai::sha256_hex(LIB_AFTER.as_bytes());
    push_result(
        &mut messages,
        "agent_verify_lib",
        &verify_lib,
        &format!("{digest}  rust/src/lib.rs\n"),
    );

    let Some(AgenticPlan::Final(answer)) = plan_chat_step(&messages, &tools) else {
        panic!("the compact Agent composite must finish");
    };
    assert!(answer.contains("observed"), "{answer}");
}

