#[test]
fn isolated_solve_stdout_is_explicitly_transported_into_the_benchmark_tree() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("the repository root sits one level above the crate");
    let read = |path: &str| {
        std::fs::read_to_string(root.join(path)).unwrap_or_else(|error| panic!("{path}: {error}"))
    };
    let runner = read("experiments/issue_847_coding_ladder/run_coding_ladder.sh");

    for contract in [
        "patch = proc.stdout",
        "patch_file.write(patch)",
        "[\"git\", \"apply\", \"--check\", patch_path]",
        "[\"git\", \"apply\", \"--whitespace=nowarn\", patch_path]",
        "cwd=root, capture_output=True, text=True",
    ] {
        assert!(
            runner.contains(contract),
            "the ladder lost patch-transport contract `{contract}`"
        );
    }
    let check = runner
        .find("[\"git\", \"apply\", \"--check\", patch_path]")
        .expect("patch applicability check");
    let apply = runner
        .find("[\"git\", \"apply\", \"--whitespace=nowarn\", patch_path]")
        .expect("explicit patch application");
    let verify = runner
        .find("verified = subprocess.run(")
        .expect("existing effect verifier");
    assert!(
        check < apply && apply < verify,
        "the diff must be checked, applied, and only then judged in the ambient tree"
    );

    let prompts: serde_json::Value =
        serde_json::from_str(&read("experiments/issue_847_coding_ladder/prompts.json"))
            .expect("coding ladder prompts are JSON");
    for id in ["read.read_version", "lang.zh_read"] {
        let task = prompts["tasks"]
            .as_array()
            .expect("task array")
            .iter()
            .find(|task| task["id"] == id)
            .unwrap_or_else(|| panic!("missing task {id}"));
        assert_eq!(task["expect_from_file"]["path"], "rust/Cargo.toml");
        assert!(
            task.get("expect_answer").is_none(),
            "{id} must not pin a release number"
        );
    }

    let invariant = read(
        "docs/case-studies/issue-848/self-hosting-authorship/coding-task-execution-invariant.lino",
    );
    assert_eq!(
        invariant,
        concat!(
            "coding_task_execution_contract\n",
            "  record_type meta_invariant\n",
            "  source_generation \"render executable source from the formalized request, never ",
            "echo request prose\"\n",
            "  verification \"compile or inspect the exact bytes written to the requested ",
            "workspace target\"\n",
            "  scoring \"record success only after an observed_workspace_effect passes its ",
            "task verifier\"",
        )
    );

    let session = "ses_04160c59fffe3FDUKteR56kfQp";
    let agent_log = read("docs/case-studies/issue-848/self-hosting-authorship/agent-cli.log");
    assert!(agent_log.contains(session));
    let formal_ai_log = read("docs/case-studies/issue-848/self-hosting-authorship/formal-ai.log");
    for transition in [
        "planned ToolCalls",
        "tool=write",
        "tool: \"bash\"",
        "planned Final",
        "coding-task-execution-invariant.lino",
    ] {
        assert!(
            formal_ai_log.contains(transition),
            "server trace is missing {transition}"
        );
    }

    let decomposition =
        read("docs/case-studies/issue-848/self-hosting-authorship/decomposition.lino");
    assert_eq!(decomposition.matches("issue_848_smallest_leaf_").count(), 7);
    assert_eq!(
        decomposition
            .matches("authorship formal_ai_agent_cli")
            .count(),
        4
    );
    for session in [
        session,
        "ses_03d2e0597ffeAUZhq3qAtj2I4U",
        "ses_03d2df24effeijLfzPXiUeV4pG",
        "ses_03d2ddb1cffeQkS5gxWjpMojc6",
    ] {
        assert!(decomposition.contains(&format!("session {session}")));
    }
    assert!(decomposition.contains("formal_ai_authored_percent 57"));
}

#[test]
fn case_study_and_release_trace_every_issue_848_acceptance_boundary() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("the repository root sits one level above the crate");
    let read = |path: &str| {
        std::fs::read_to_string(root.join(path)).unwrap_or_else(|error| panic!("{path}: {error}"))
    };
    let case_study = read("docs/case-studies/issue-848/README.md");
    for evidence in [
        "38/130",
        "61/130",
        "62/130",
        "65/130",
        "compiler-valid",
        "test_authoring",
        "targeted_edit",
        "multilingual",
        "ses_04160c59fffe3FDUKteR56kfQp",
    ] {
        assert!(case_study.contains(evidence), "missing {evidence}");
    }

    let traceability = read("docs/case-studies/issue-848/requirements.md");
    for index in 1..=10 {
        assert!(
            traceability.contains(&format!("R848-{index}")),
            "missing R848-{index}"
        );
    }
    let global = crate::assembled_docs::requirements();
    assert!(global.contains("## Issue #848"));
    assert!(global.contains("R848-10"));

    // Release automation consumes changelog fragments after copying them into
    // CHANGELOG.md. Keep the trace valid both before and after that lifecycle,
    // matching the established issue #656/#844 requirements checks.
    let fragment_path = root.join("changelog.d/20260801_848_coding_tasks.md");
    if fragment_path.is_file() {
        let fragment = std::fs::read_to_string(fragment_path).expect("read issue #848 fragment");
        assert!(fragment.contains("bump: minor"));
        assert!(fragment.contains("#848"));
    } else {
        assert!(
            crate::assembled_docs::changelog().contains("issue #848's 130-task coding ladder"),
            "issue #848 must have either its unreleased minor-bump fragment or its released CHANGELOG entry"
        );
        assert!(
            read("docs/case-studies/issue-711/fragment-release-map.tsv")
                .lines()
                .any(|line| line == "changelog.d/20260801_848_coding_tasks.md\t0.322.0"),
            "the consumed issue #848 fragment must map to its release"
        );
    }
}

fn assert_generated_source(task: &str, path: &str, expected: &str) {
    let outcome = run_agentic_task(task).expect("isolated agent workspace");
    assert!(
        !outcome.hit_turn_cap,
        "agent loop must terminate: {outcome:?}"
    );

    let write = outcome
        .steps
        .iter()
        .find(|step| {
            step.tool == "write_file"
                && serde_json::from_str::<serde_json::Value>(&step.arguments)
                    .ok()
                    .and_then(|arguments| arguments["path"].as_str().map(str::to_owned))
                    .is_some_and(|written| written == path)
        })
        .unwrap_or_else(|| panic!("requested file was not written: {outcome:?}"));
    let arguments: serde_json::Value =
        serde_json::from_str(&write.arguments).expect("write arguments are JSON");
    assert_eq!(arguments["content"], expected, "generated source: {task}");
    assert!(
        outcome.steps.iter().any(|step| {
            step.tool == "run_command"
                && step.arguments.contains(&format!("cat {path}"))
                && step.result == expected
        }),
        "verification must observe the generated bytes: {outcome:?}"
    );
}

#[track_caller]
fn only_call(plan: Option<AgenticPlan>) -> formal_ai::agentic_coding::PlannedToolCall {
    match plan {
        Some(AgenticPlan::ToolCalls(mut calls)) => {
            assert_eq!(calls.len(), 1);
            calls.remove(0)
        }
        other => panic!("expected one tool call, got {other:?}"),
    }
}

fn json_arguments(arguments: &str) -> serde_json::Value {
    serde_json::from_str(arguments).expect("tool arguments are JSON")
}

fn push_result(
    messages: &mut Vec<ChatMessage>,
    id: &str,
    call: &formal_ai::agentic_coding::PlannedToolCall,
    result: &str,
) {
    messages.push(ChatMessage::assistant_tool_calls(vec![ToolCall::function(
        id.to_owned(),
        call.tool.clone(),
        call.arguments.clone(),
    )]));
    messages.push(ChatMessage::tool_result(
        id.to_owned(),
        call.tool.clone(),
        result.to_owned(),
    ));
}

#[test]
fn generated_source_reads_existing_target_before_replacement() {
    let task = "Create rust/src/held_out.rs containing a public Rust function named held_out_value returning 29.";
    let mut messages = vec![ChatMessage::user(task)];
    let Some(AgenticPlan::ToolCalls(calls)) =
        plan_chat_step(&messages, &["read_file", "write_file"])
    else {
        panic!("preimage must be observed");
    };
    assert_eq!(calls.len(), 1);
    assert_eq!(calls[0].tool, "read_file");
    let arguments: serde_json::Value =
        serde_json::from_str(&calls[0].arguments).expect("read arguments");
    assert_eq!(arguments["path"], "rust/src/held_out.rs");
    messages.push(ChatMessage::assistant_tool_calls(vec![ToolCall::function(
        "preimage",
        &calls[0].tool,
        &calls[0].arguments,
    )]));
    messages.push(ChatMessage::tool_result(
        "preimage",
        "read_file",
        "pub fn existing() {}\n",
    ));
    let Some(AgenticPlan::Final(answer)) = plan_chat_step(&messages, &["read_file", "write_file"])
